# Compare them
def deep_diff(a, b, path=''):
    if type(a) != type(b):
        print(f'  TYPE {path}: {type(a).__name__} vs {type(b).__name__}')
        return
    if isinstance(a, dict):
        for k in set(list(a.keys()) + list(b.keys())):
            if k not in a:
                print(f'  EXTRA_B {path}.{k}: {repr(b[k])[:100]}')
            elif k not in b:
                print(f'  MISSING_B {path}.{k}: {repr(a[k])[:100]}')
            else:
                deep_diff(a[k], b[k], f'{path}.{k}')
    elif isinstance(a, list):
        if len(a) != len(b):
            print(f'  LEN {path}: {len(a)} vs {len(b)}')
        for i in range(min(len(a), len(b))):
            deep_diff(a[i], b[i], f'{path}[{i}]')
    elif a != b:
        print(f'  DIFF {path}: {repr(a)[:100]} vs {repr(b)[:100]}')

print('DIFFERENCES:')
deep_diff(kit_dict, imported_dict)
